def txt(s,x,y,w,st=style):
 p=Paragraph(s,st);_,h=p.wrap(w,2000);p.drawOn(C,x,y-h);return h

def page(title,sub):
 global num
 num+=1;C.setFillColor(colors.white);C.rect(0,0,W,H,fill=1,stroke=0);C.setFillColor(INK);C.rect(0,H-12,W,12,fill=1,stroke=0);C.setFont('B',10);C.drawString(M,H-36,'СПИМ С ХАСКИ / ЛЕЖАНДР / R08');C.setFont('R',9);C.drawRightString(W-M,H-36,'04.10.2026 • мм • цифровой прототип P0')
 C.setFont('B',25);C.drawString(M,H-78,title);txt(sub,M,H-96,W-2*M)
 C.setStrokeColor(LIGHT);C.line(M,41,W-M,41);C.setFont('R',8);C.setFillColor(MUTED);C.drawString(M,24,'Номинальная CAD-геометрия. Не сертификат прочности, тепловой безопасности или производственного раскроя.');C.drawRightString(W-M,24,f'{num:02}')
 C.bookmarkPage(f'p{num}');C.addOutlineEntry(title,f'p{num}',0,False)
def pic(p,x=M,y=166,w=W-2*M,h=528):
 im=Image.open(ROOT/p).convert('RGB');a=np.array(im);mask=a.mean(2)<222
 if 'renders/' in str(p) and 'actual' not in str(p):
  yy,xx=np.where(mask)
  if len(xx):im=im.crop((max(0,xx.min()-35),max(0,yy.min()-35),min(im.width,xx.max()+35),min(im.height,yy.max()+35)))
 s=min(w/im.width,h/im.height);C.drawImage(ImageReader(im),x+(w-im.width*s)/2,y+(h-im.height*s)/2,im.width*s,im.height*s)
def note(s,y=123):txt(s,M,y,W-2*M)
def table(rows,widths,y=650):
 data=[[Paragraph(str(v),small) for v in row] for row in rows];t=Table(data,colWidths=widths,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),LIGHT),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9),('LINEBELOW',(0,0),(-1,0),.8,MUTED),('LINEBELOW',(0,1),(-1,-1),.25,LIGHT)]));_,h=t.wrap(W-2*M,1000);t.drawOn(C,M,y-h);return h
